REVOKE ALL ON FUNCTION public.complete_customer_onboarding(text,text[],text[],boolean) FROM authenticated;
CREATE FUNCTION public.finalize_customer_account(p_user_id uuid, p_pin_hash text, p_question_ids text[], p_answer_hashes text[], p_biometric boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE account_id uuid; BEGIN IF array_length(p_question_ids, 1) <> 3 OR array_length(p_answer_hashes, 1) <> 3 OR length(p_pin_hash) < 80 THEN RAISE EXCEPTION 'Invalid security data'; END IF; IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_user_id AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Confirm email first'; END IF; IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id AND onboarding_step = 5) THEN RAISE EXCEPTION 'Complete application first'; END IF; INSERT INTO public.customer_security VALUES (p_user_id, p_pin_hash, p_question_ids, p_answer_hashes, p_biometric) ON CONFLICT (user_id) DO NOTHING; INSERT INTO public.customer_accounts(user_id, terms_version, privacy_version, identity_consent_at) VALUES (p_user_id, 'onboarding-notice-2026-10', 'privacy-notice-2026-10', now()) ON CONFLICT (user_id) DO NOTHING; SELECT id INTO account_id FROM public.customer_accounts WHERE user_id = p_user_id; RETURN account_id; END; $$;
REVOKE ALL ON FUNCTION public.finalize_customer_account(uuid,text,text[],text[],boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.finalize_customer_account(uuid,text,text[],text[],boolean) TO service_role;